//! NEW bounded live resource/control kernel. Accepted captured17c9 source unchanged.
#[path="../../fdn-room-live/src/timeline.rs"]mod timeline;
#[cfg(feature="allocation-audit")]mod allocation;
const Q:usize=128;const N:usize=44100;const SLOTS:usize=8;const COMMANDS:usize=32;const CHUNK:usize=1024;
struct Resource{generation:u32,state:u32,drive:f64,written:usize,references:u32,data:Vec<f32>}
impl Resource{fn new()->Self{Self{generation:0,state:0,drive:0.,written:0,references:0,data:vec![0.;N]}}}
#[derive(Clone,Copy)]struct Command{kind:u32,lane:usize,value:f64,slot:usize,generation:u32,author:u64,seconds:f64}
const EMPTY:Command=Command{kind:0,lane:0,value:0.,slot:0,generation:0,author:0,seconds:0.};
pub struct Engine{rate:f64,channels:usize,resources:[Resource;SLOTS],active:Option<usize>,ready:bool,frame:u64,origin:u64,lanes:[timeline::LiveTimeline;2],targets:[f64;2],queue:[Command;COMMANDS],queued:usize,last_author:u64,service:Option<u64>,service_floats:usize,scratch:[f32;CHUNK],input:[[f32;Q];2],output:[[f32;Q];2],wet:[[f32;Q];2],calls:u64,rendered:u64,unpulled:u64,applied:u64,curve_assignments:u64,uploaded:u64,rejected:u64,peak:f64,initial_steps:usize}
fn index(v:f64,max:usize)->Option<usize>{if v.is_finite()&&v>=0.&&v.fract()==0.&&v<=max as f64{Some(v as usize)}else{None}}
fn canonical(v:f64)->bool{v.is_finite()&&v>=0.&&v<=9007199254740864.&&v%128.==0.}
fn finite(v:f64)->bool{v.is_finite()&&(v as f32).is_finite()}
fn shape(x:f32,data:&[f32])->f32{let virtual_index=((x+1.)*((N-1)as f32*0.5)).clamp(0.,(N-1)as f32);let at=virtual_index as usize;let next=(at+1).min(N-1);let f=virtual_index-at as f32;let delta=data[next]-data[at];let scaled=f*delta;scaled+data[at]}
impl Engine{
 fn new(rate:f64,channels:usize)->Option<Box<Self>>{if !rate.is_finite()||rate.fract()!=0.||!(8000. ..=192000.).contains(&rate)||!(1..=2).contains(&channels){return None;}Some(Box::new(Self{rate,channels,resources:std::array::from_fn(|_|Resource::new()),active:None,ready:false,frame:0,origin:0,lanes:std::array::from_fn(|_|timeline::LiveTimeline::new(1.,257,rate)),targets:[1.;2],queue:[EMPTY;COMMANDS],queued:0,last_author:0,service:None,service_floats:0,scratch:[0.;CHUNK],input:[[0.;Q];2],output:[[0.;Q];2],wet:[[0.;Q];2],calls:0,rendered:0,unpulled:0,applied:0,curve_assignments:0,uploaded:0,rejected:0,peak:0.,initial_steps:0}))}
 fn reject(&mut self)->bool{self.rejected+=1;false}
 fn resource_ready(&self,slot:usize,g:u32)->bool{self.resources[slot].state==2&&self.resources[slot].generation==g}
 fn reserve(&mut self,slot:usize,g:u32,drive:f64)->bool{let r=&self.resources[slot];if !drive.is_finite()||!(0. ..=30.).contains(&drive)||g==0||r.generation==u32::MAX||g!=r.generation+1||r.state!=0||self.active==Some(slot)||r.references!=0{return self.reject();}let r=&mut self.resources[slot];r.generation=g;r.state=1;r.drive=drive;r.written=0;true}
 fn service(&mut self,ordinal:u64)->bool{if !self.ready||self.service.is_some_and(|n|ordinal<=n){return self.reject();}self.service=Some(ordinal);self.service_floats=0;true}
 fn upload(&mut self,slot:usize,g:u32,offset:usize,n:usize)->bool{let r=&self.resources[slot];if n==0||n>CHUNK||r.state!=1||r.generation!=g||offset!=r.written||offset+n>N||self.ready&&(self.service.is_none()||self.service_floats+n>CHUNK)||self.scratch[..n].iter().any(|v|!v.is_finite()){return self.reject();}self.resources[slot].data[offset..offset+n].copy_from_slice(&self.scratch[..n]);self.resources[slot].written+=n;self.service_floats+=n;self.uploaded+=n as u64;true}
 fn seal(&mut self,slot:usize,g:u32)->bool{let r=&mut self.resources[slot];if r.state!=1||r.generation!=g||r.written!=N{return self.reject();}r.state=2;true}
 fn release(&mut self,slot:usize,g:u32)->bool{let r=&self.resources[slot];if !self.resource_ready(slot,g)||self.active==Some(slot)||r.references!=0{return self.reject();}self.resources[slot].state=0;true}
 fn time(&self,author:f64,seconds:f64)->bool{canonical(author)&&seconds.is_finite()&&seconds==author/self.rate}
 fn initial_lane(&mut self,lane:usize,value:f64,author:f64,seconds:f64)->bool{if self.ready||!self.time(author,seconds)||!finite(value)||author<self.last_author as f64||self.initial_steps>=128||!self.lanes[lane].available_at(1,author){return self.reject();}if self.initial_steps==0&&(lane!=0||value!=1.)||self.initial_steps==1&&(lane!=1||value!=0.){return self.reject();}self.lanes[lane].prune_for_insert(author);assert!(self.lanes[lane].add_seconds(seconds,0,value,0.));self.targets[lane]=value;self.last_author=author as u64;self.initial_steps+=1;true}
 fn initial_curve(&mut self,slot:usize,g:u32,author:f64,seconds:f64)->bool{if self.ready||self.initial_steps<2||self.initial_steps>=128||!self.time(author,seconds)||author<self.last_author as f64||!self.resource_ready(slot,g){return self.reject();}self.active=Some(slot);self.curve_assignments+=1;self.initial_steps+=1;self.last_author=author as u64;true}
 fn prepare(&mut self,origin:f64,slot:usize,g:u32)->bool{if self.ready||!canonical(origin)||origin<self.last_author as f64||self.initial_steps<2||!self.resource_ready(0,1)||!self.resource_ready(1,1)||self.resources[0].drive!=0.||self.resources[1].drive!=0.||!self.resource_ready(slot,g)||self.active.is_some_and(|active|active!=slot){return self.reject();}self.active=Some(slot);self.curve_assignments+=2;self.frame=origin as u64;self.origin=self.frame;self.ready=true;true}
 fn sync(&mut self,frame:f64)->bool{if !self.ready||!canonical(frame)||frame<self.frame as f64||frame-self.origin as f64>self.rate*3600.||self.queued!=0{return self.reject();}self.frame=frame as u64;true}
 fn enqueue(&mut self,c:Command)->bool{if !self.ready||self.queued>=COMMANDS||!self.time(c.author as f64,c.seconds)||c.author<self.last_author||c.author<self.origin||c.author>self.frame||c.kind==0&&(!finite(c.value)||!self.lanes[c.lane].available_at(self.queue[..self.queued].iter().filter(|e|e.kind==0&&e.lane==c.lane).count()+1,self.frame as f64))||c.kind==1&&(!self.resource_ready(c.slot,c.generation)||self.resources[c.slot].references>=32){return self.reject();}if c.kind==1{self.resources[c.slot].references+=1;}self.last_author=c.author;self.queue[self.queued]=c;self.queued+=1;true}
 fn commit(&mut self)->bool{if !self.ready{return self.reject();}for lane in 0..2{let n=self.queue[..self.queued].iter().filter(|c|c.kind==0&&c.lane==lane).count();if !self.lanes[lane].available_at(n,self.frame as f64){return self.reject();}}for i in 0..self.queued{let c=self.queue[i];if c.kind==0{self.lanes[c.lane].prune_for_insert(self.frame as f64);assert!(self.lanes[c.lane].add_seconds(c.seconds,0,c.value,0.));self.targets[c.lane]=c.value;}else{assert!(self.resource_ready(c.slot,c.generation));self.active=Some(c.slot);self.resources[c.slot].references-=1;self.curve_assignments+=1;}self.applied+=1;}self.queued=0;true}
 fn render(&mut self,channels:usize,pulled:bool)->bool{if !self.ready||self.queued!=0||self.frame+128-self.origin>self.rate as u64*3600||channels>2||channels!=0&&channels!=self.channels||!pulled&&channels!=0||(0..channels).any(|c|self.input[c].iter().any(|v|!v.is_finite())){return self.reject();}self.output.fill([0.;Q]);self.wet.fill([0.;Q]);self.peak=0.;if pulled{for lane in &mut self.lanes{lane.prepare(self.frame,self.rate);}let data=&self.resources[self.active.unwrap()].data;for c in 0..self.channels{for i in 0..Q{let input=if channels>0{self.input[c][i]}else{0.};let shaped=shape(input,data);let dry=input*self.lanes[0].output[i];let wet=shaped*self.lanes[1].output[i];let y=dry+wet;if !y.is_finite(){return self.reject();}self.wet[c][i]=shaped;self.output[c][i]=y;self.peak=self.peak.max(y.abs()as f64);}}self.rendered+=128;}else{self.unpulled+=128;}self.frame+=128;self.calls+=1;true}
}
#[no_mangle]pub extern "C" fn distortion_live_api()->u32{1}
#[no_mangle]pub extern "C" fn distortion_live_new(rate:f64,channels:f64)->*mut Engine{index(channels,2).and_then(|n|Engine::new(rate,n)).map(Box::into_raw).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub unsafe extern "C" fn distortion_live_free(p:*mut Engine){if !p.is_null(){drop(Box::from_raw(p));}}
#[no_mangle]pub extern "C" fn distortion_live_reserve(p:&mut Engine,s:f64,g:f64,drive:f64)->u32{match(index(s,7),index(g,u32::MAX as usize)){(Some(s),Some(g))=>p.reserve(s,g as u32,drive)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_upload(p:&mut Engine,s:f64,g:f64,o:f64,n:f64)->u32{match(index(s,7),index(g,u32::MAX as usize),index(o,N),index(n,CHUNK)){(Some(s),Some(g),Some(o),Some(n))=>p.upload(s,g as u32,o,n)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_seal(p:&mut Engine,s:f64,g:f64)->u32{match(index(s,7),index(g,u32::MAX as usize)){(Some(s),Some(g))=>p.seal(s,g as u32)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_release(p:&mut Engine,s:f64,g:f64)->u32{match(index(s,7),index(g,u32::MAX as usize)){(Some(s),Some(g))=>p.release(s,g as u32)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_service(p:&mut Engine,n:f64)->u32{(n.is_finite()&&n>=0.&&n.fract()==0.&&n<=9007199254740991.&&p.service(n as u64))as u32}
#[no_mangle]pub extern "C" fn distortion_live_initial(p:&mut Engine,lane:f64,value:f64,author:f64,seconds:f64)->u32{index(lane,1).is_some_and(|lane|p.initial_lane(lane,value,author,seconds))as u32}
#[no_mangle]pub extern "C" fn distortion_live_prepare(p:&mut Engine,origin:f64,s:f64,g:f64)->u32{match(index(s,7),index(g,u32::MAX as usize)){(Some(s),Some(g))=>p.prepare(origin,s,g as u32)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_sync(p:&mut Engine,frame:f64)->u32{p.sync(frame)as u32}
#[no_mangle]pub extern "C" fn distortion_live_lane(p:&mut Engine,lane:f64,value:f64,author:f64,seconds:f64)->u32{if !p.time(author,seconds){return p.reject()as u32;}index(lane,1).is_some_and(|lane|p.enqueue(Command{kind:0,lane,value,author:author as u64,seconds,..EMPTY}))as u32}
#[no_mangle]pub extern "C" fn distortion_live_curve(p:&mut Engine,s:f64,g:f64,author:f64,seconds:f64)->u32{if !p.time(author,seconds){return p.reject()as u32;}match(index(s,7),index(g,u32::MAX as usize)){(Some(slot),Some(generation))=>p.enqueue(Command{kind:1,slot,generation:generation as u32,author:author as u64,seconds,..EMPTY})as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_commit(p:&mut Engine)->u32{p.commit()as u32}
#[no_mangle]pub extern "C" fn distortion_live_render(p:&mut Engine,c:f64,pulled:f64)->u32{match(index(c,2),index(pulled,1)){(Some(c),Some(v))=>p.render(c,v==1)as u32,_=>p.reject()as u32}}
#[no_mangle]pub extern "C" fn distortion_live_scratch(p:&mut Engine)->*mut f32{p.scratch.as_mut_ptr()}
#[no_mangle]pub extern "C" fn distortion_live_input(p:&mut Engine,c:u32)->*mut f32{p.input.get_mut(c as usize).map_or(std::ptr::null_mut(),|v|v.as_mut_ptr())}
#[no_mangle]pub extern "C" fn distortion_live_output(p:&Engine,c:u32)->*const f32{p.output.get(c as usize).map_or(std::ptr::null(),|v|v.as_ptr())}
#[no_mangle]pub extern "C" fn distortion_live_wet(p:&Engine,c:u32)->*const f32{p.wet.get(c as usize).map_or(std::ptr::null(),|v|v.as_ptr())}
#[no_mangle]pub extern "C" fn distortion_live_slot(p:&Engine,s:u32,i:u32)->f64{p.resources.get(s as usize).map_or(f64::NAN,|r|match i{0=>r.generation as f64,1=>r.state as f64,2=>r.drive,3=>r.written as f64,4=>r.references as f64,5=>(p.active==Some(s as usize))as u32 as f64,_=>f64::NAN})}
#[no_mangle]pub extern "C" fn distortion_live_stat(p:&Engine,i:u32)->f64{match i{0=>p.frame as f64,1=>p.peak,2=>p.calls as f64,3=>p.rendered as f64,4=>p.unpulled as f64,5=>p.applied as f64,6=>p.rejected as f64,7=>p.active.map_or(-1.,|s|s as f64),8=>p.queued as f64,9=>p.curve_assignments as f64,10=>p.uploaded as f64,11=>p.service_floats as f64,12=>p.ready as u32 as f64,13=>p.origin as f64,14=>p.targets[0],15=>p.targets[1],16=>p.lanes[0].output[127]as f64,17=>p.lanes[1].output[127]as f64,_=>f64::NAN}}

#[no_mangle]pub extern "C" fn distortion_live_capacity(p:&Engine,lane:f64,count:f64)->u32{match(index(lane,1),index(count,32)){(Some(lane),Some(n))=>(p.ready&&p.queued+n<=COMMANDS&&p.lanes[lane].available_at(n+p.queue[..p.queued].iter().filter(|c|c.kind==0&&c.lane==lane).count(),p.frame as f64))as u32,_=>0}}

#[no_mangle]pub extern "C" fn distortion_live_initial_curve(p:&mut Engine,s:f64,g:f64,author:f64,seconds:f64)->u32{match(index(s,7),index(g,u32::MAX as usize)){(Some(s),Some(g))=>p.initial_curve(s,g as u32,author,seconds)as u32,_=>p.reject()as u32}}
